void unit_test_compileFromAST_empty_ast_node(void) {
    // Setup: create an ASTNode with content == '\0' (empty input)
    struct ASTNode* root = createNode('\0');
    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_EQUAL('\0', root->content);
    TEST_ASSERT_NULL(root->left);
    TEST_ASSERT_NULL(root->right);

    // Test: compile the AST to NFA
    struct NFA* nfa = compileFromAST(root);

    // Assertions: NFA should be created and not NULL
    TEST_ASSERT_NOT_NULL(nfa);

    // Optionally, check that the NFA accepts the empty string and rejects non-empty
    helper_assert_nfa_accepts("", "", 1);      // Should accept empty string
    helper_assert_nfa_accepts("", "a", 0);     // Should not accept non-empty string

    // Cleanup
    destroyNFA(nfa);
    destroyNode(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_compileFromAST_empty_ast_node);
    return UNITY_END();
}


